return await (async function () {

const CLIENT_ID = 'YOUR_EBAY_CLIENT_ID';
const CLIENT_SECRET = 'YOUR_EBAY_CLIENT_SECRET';
const REFRESH_TOKEN = 'YOUR_EBAY_REFRESH_TOKEN';
const MARKETPLACE_ID = 'EBAY_US';
const ORDER_LOOKBACK_DAYS = 90;
const PAGE_LIMIT = 100;

const input = $input.first().json;
const userText = input.text || '';
const chatId = input.chatId;
const firstName = input.firstName || '';
const b64 = Buffer.from(CLIENT_ID + ':' + CLIENT_SECRET).toString('base64');

function mv(m) { return Number(m?.value || 0); }
function dateLA(v) { return v ? new Date(v).toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' }) : null; }

async function getToken(scope) {
  const r = await this.helpers.request({ method: 'POST', url: 'https://api.ebay.com/identity/v1/oauth2/token', headers: { 'Authorization': 'Basic ' + b64, 'Content-Type': 'application/x-www-form-urlencoded' }, form: { grant_type: 'refresh_token', refresh_token: REFRESH_TOKEN, scope } });
  const j = typeof r === 'string' ? JSON.parse(r) : r;
  if (!j.access_token) throw new Error(j.error_description || 'no token');
  return j.access_token;
}

async function apiGet(url, token) {
  const r = await this.helpers.request({ method: 'GET', url, headers: { 'Authorization': 'Bearer ' + token } });
  return typeof r === 'string' ? JSON.parse(r) : r;
}

async function getPaged(url, token, key) {
  const out = []; let offset = 0;
  for (let p = 0; p < 20; p++) {
    const sep = url.includes('?') ? '&' : '?';
    const data = await apiGet.call(this, url + sep + 'limit=' + PAGE_LIMIT + '&offset=' + offset, token);
    const rows = data[key] || [];
    out.push(...rows);
    const total = typeof data.total === 'number' ? data.total : out.length;
    if (!rows.length || out.length >= total || !data.next) break;
    offset += PAGE_LIMIT;
  }
  return out;
}

async function safe(label, fn) {
  try { return { ok: true, data: await fn() }; }
  catch (e) { return { ok: false, error: label + ': ' + (e.message || String(e)) }; }
}

function summarizeOrders(orders) {
  const byDate = {}, byItem = {};
  let gross = 0, dueSeller = 0, unshipped = 0, refunded = 0;
  for (const o of orders) {
    const d = dateLA(o.creationDate) || 'unknown';
    const amt = mv(o.pricingSummary?.total);
    gross += amt; dueSeller += mv(o.paymentSummary?.totalDueSeller);
    byDate[d] = byDate[d] || { orders: 0, gross: 0 };
    byDate[d].orders++; byDate[d].gross += amt;
    if (o.orderFulfillmentStatus !== 'FULFILLED') unshipped++;
    if ((o.paymentSummary?.refunds || []).length) refunded++;
    for (const item of o.lineItems || []) {
      const k = item.sku || item.title || 'unknown';
      byItem[k] = byItem[k] || { title: item.title || 'N/A', quantity: 0, revenue: 0 };
      byItem[k].quantity += Number(item.quantity || 0);
      byItem[k].revenue += mv(item.lineItemCost) * Number(item.quantity || 1);
    }
  }
  return { count: orders.length, gross, dueSeller, unshipped, refunded, byDate, topItems: Object.values(byItem).sort((a,b) => b.revenue - a.revenue).slice(0,20) };
}

function summarizeOffers(offers) {
  let pub = 0, unpub = 0; const low = [], unpubList = [];
  for (const o of offers) {
    const st = o.status || o.listing?.listingStatus || 'UNKNOWN';
    const isPub = st === 'PUBLISHED' || st === 'ACTIVE';
    if (isPub) pub++;
    else { unpub++; unpubList.push({ sku: o.sku, status: st }); }
    const qty = Number(o.availableQuantity ?? 0);
    if (qty > 0 && qty <= 2) low.push({ sku: o.sku, quantity: qty });
  }
  return { count: offers.length, published: pub, unpublished: unpub, lowQuantity: low.slice(0,30), unpublishedOffers: unpubList.slice(0,30) };
}

function summarizeInventory(items) {
  let noImg = 0, noAsp = 0; const low = [], oos = [];
  const catMap = {};
  for (const item of items) {
    if (!(item.product?.imageUrls||[]).length) noImg++;
    if (!Object.keys(item.product?.aspects||{}).length) noAsp++;
    const qty = Number(item.availability?.shipToLocationAvailability?.quantity || 0);
    const s = { sku: item.sku, title: item.product?.title || null, quantity: qty };
    if (qty === 0) oos.push(s); else if (qty <= 2) low.push(s);
    const types = item.product?.aspects?.Type || item.product?.aspects?.type || [];
    const depts = item.product?.aspects?.Department || item.product?.aspects?.department || [];
    for (const t of types) { catMap[t] = (catMap[t] || 0) + 1; }
    for (const d of depts) { catMap[d] = (catMap[d] || 0) + 1; }
  }
  const categories = Object.entries(catMap).sort((a,b) => b[1]-a[1]).map(([name,count]) => ({ name, count }));
  return { count: items.length, missingImages: noImg, missingAspects: noAsp, lowStock: low.slice(0,30), outOfStock: oos.slice(0,30), categories };
}

const since = new Date(Date.now() - ORDER_LOOKBACK_DAYS * 86400000).toISOString();
const tF = await getToken.call(this, 'https://api.ebay.com/oauth/api_scope/sell.fulfillment.readonly');
const tI = await getToken.call(this, 'https://api.ebay.com/oauth/api_scope/sell.inventory.readonly');
const tM = await getToken.call(this, 'https://api.ebay.com/oauth/api_scope/sell.marketing.readonly');

const ordersR    = await safe('orders',    () => getPaged.call(this, 'https://api.ebay.com/sell/fulfillment/v1/order?filter=creationdate:[' + since + '..]', tF, 'orders'));
const offersR    = await safe('offers',    () => getPaged.call(this, 'https://api.ebay.com/sell/inventory/v1/offer', tI, 'offers'));
const inventoryR = await safe('inventory', () => getPaged.call(this, 'https://api.ebay.com/sell/inventory/v1/inventory_item', tI, 'inventoryItems'));
const promoR     = await safe('promos',    () => getPaged.call(this, 'https://api.ebay.com/sell/marketing/v1/promotion?marketplace_id=' + MARKETPLACE_ID, tM, 'promotions'));
const campR      = await safe('campaigns', () => getPaged.call(this, 'https://api.ebay.com/sell/marketing/v1/ad_campaign', tM, 'campaigns'));
const tFinR      = await safe('fin_token', () => getToken.call(this, 'https://api.ebay.com/oauth/api_scope/sell.finances'));
const finR       = tFinR.ok ? await safe('transactions', () => getPaged.call(this, 'https://apiz.ebay.com/sell/finances/v1/transaction?filter=transactionDate:[' + since + '..]', tFinR.data, 'transactions')) : { ok: false, error: 'finances not authorized' };

const orders     = ordersR.ok    ? ordersR.data    : [];
const offers     = offersR.ok    ? offersR.data    : [];
const inventory  = inventoryR.ok ? inventoryR.data : [];
const promotions = promoR.ok     ? promoR.data     : [];
const campaigns  = campR.ok      ? campR.data      : [];
const txns       = finR.ok       ? finR.data       : [];
const errors     = [ordersR, offersR, inventoryR, promoR, campR, finR].filter(x => !x.ok).map(x => x.error);

return [{ json: { chatId, userText, firstName, fetchedAt: new Date().toISOString(), dataWindow: { days: ORDER_LOOKBACK_DAYS, since }, errors, summary: { orders: summarizeOrders(orders), offers: summarizeOffers(offers), inventory: summarizeInventory(inventory), promotions: promotions.map(p => ({ name: p.name, status: p.promotionStatus, startDate: p.startDate, endDate: p.endDate })).slice(0,50), adCampaigns: campaigns.map(c => ({ name: c.campaignName || c.name, status: c.campaignStatus, type: c.campaignType })).slice(0,50), finances: { loaded: txns.length } }, rawOrders: orders.slice(0,50), rawOffers: offers.slice(0,100), rawInventory: inventory.slice(0,100) } }];
}).call(this);

const OPENAI_KEY = 'YOUR_OPENAI_API_KEY';
const d = $input.first().json;
if (!d.summary) return [{ json: { chatId: d.chatId, reply: 'eBay data error.' } }];
const s = d.summary;
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
const byDate = s.orders.byDate || {};
const l7 = Object.entries(byDate).filter(([dt]) => new Date(dt) >= new Date(Date.now()-7*86400000));
const l30 = Object.entries(byDate).filter(([dt]) => new Date(dt) >= new Date(Date.now()-30*86400000));
const r7 = l7.reduce((s,[,v]) => s+v.gross, 0).toFixed(2);
const c7 = l7.reduce((s,[,v]) => s+v.orders, 0);
const r30 = l30.reduce((s,[,v]) => s+v.gross, 0).toFixed(2);
const c30 = l30.reduce((s,[,v]) => s+v.orders, 0);

const activeListings = s.offers.published > 0 ? s.offers.published : s.inventory.count;
const listingSource = s.offers.published > 0 ? 'offers API' : 'inventory items count';

const cats = (s.inventory.categories || []).map(c => c.name + '(' + c.count + ')').join(', ');

const system = 'You are an eBay seller assistant named Prime Outlet Bot. ALWAYS reply in Armenian. Use ONLY Telegram HTML formatting: <b>text</b> for bold. NEVER use **markdown**. NEVER use asterisks.

Seller: ' + (d.firstName||'seller') + '
Today (LA time): ' + today + '
Data window: last ' + (d.dataWindow?.days||90) + ' days
Errors: ' + ((d.errors||[]).join(', ')||'none') + '

== QUICK STATS ==
Last 7 days: ' + c7 + ' orders, $' + r7 + '
Last 30 days: ' + c30 + ' orders, $' + r30 + '
90d total: ' + s.orders.count + ' orders, $' + (s.orders.gross||0).toFixed(2) + '
Unshipped: ' + s.orders.unshipped + ' | Refunded: ' + s.orders.refunded + '
Active listings: ' + activeListings + ' (source: ' + listingSource + ')
Published offers: ' + s.offers.published + ' | Total offers: ' + s.offers.count + '
Inventory items: ' + s.inventory.count + '
Low stock: ' + (s.offers.lowQuantity?.length||0) + ' | Out of stock: ' + (s.inventory.outOfStock?.length||0) + '
Missing images: ' + s.inventory.missingImages + ' | Promotions: ' + (s.promotions?.length||0) + ' | Campaigns: ' + (s.adCampaigns?.length||0) + '

== CATEGORIES (from inventory aspects) ==
' + (cats || 'none') + '

== ORDERS BY DATE (LA timezone, YYYY-MM-DD) ==
' + JSON.stringify(byDate) + '

== TOP SELLING ITEMS ==
' + JSON.stringify(s.orders.topItems) + '

== PROMOTIONS ==
' + JSON.stringify(s.promotions) + '

== AD CAMPAIGNS ==
' + JSON.stringify(s.adCampaigns) + '

== OFFERS SUMMARY ==
' + JSON.stringify(s.offers) + '

== RAW ORDERS ==
' + JSON.stringify(d.rawOrders) + '

RULES:
- All dates are in LA timezone (America/Los_Angeles)
- Answer ONLY from data above, do not guess
- For date questions: look up byDate object using exact YYYY-MM-DD key
- If a date has no entry in byDate = 0 orders that day
- Active listings count = inventory items count (' + s.inventory.count + ') since all listings were created via API
- promotions = sale events, coupons, markdowns
- campaigns = PPC promoted listings
- Max 8 lines per answer
- Use <b>bold</b> for all numbers';

try {
  const r = await this.helpers.request({ method: 'POST', url: 'https://api.openai.com/v1/chat/completions', headers: { 'Authorization': 'Bearer ' + OPENAI_KEY, 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'gpt-4o-mini', max_tokens: 1200, temperature: 0.1, messages: [{ role: 'system', content: system }, { role: 'user', content: d.userText }] }) });
  const result = typeof r === 'string' ? JSON.parse(r) : r;
  return [{ json: { chatId: d.chatId, reply: result.choices?.[0]?.message?.content || 'Սխալ' } }];
} catch(e) {
  return [{ json: { chatId: d.chatId, reply: 'AI error: ' + e.message } }];
}
